/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNumberArray = require( '@stdlib/assert/is-number-array' );
var format = require( '@stdlib/string/format' );

/**
* Validate the array.
*
* @private
* @param {Array} value - array of axises data
* @throws {TypeError}
*/
function validate( value ) {
	if ( !isNumberArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array of number. Value: `%s`.', 'axis-label-format', value ) );
	}
	if ( value.length !== 4 ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array of length 4. Value: `%s`.', 'axis-label-format', value ) );
	}
}


// MAIN //

/**
* Sets the axis label formate.
* Note: space require between each tics label in axis is in control of the specific plot package.
* It is the short hand for xTicSpacing, yTicSpacing, zTicSpacing and wTicSpacing
*
* @private
* @param {Array} value - Array of tics space.
* @throws {TypeError} must be a array of number with length 4
*/
function set( value ) {
	validate( value );
	this.xTicSpacing = value[ 0 ];
	this.yTicSpacing = value[ 1 ];
	this.zTicSpacing = value[ 2 ];
	this.wTicSpacing = value[ 3 ];
}


// EXPORTS //

module.exports = set;
